image.asymptote:
import three;
size(6.5cm);
currentprojection=orthographic(7,-10,7);
path3 rim=(1.5,0,0), travel=(1.5,0,0);
for(int k=1; k<72; ++k) {
  real t=2pi*k/72;
  rim=rim--(1.5*cos(t),1.5*sin(t),0);
}
for(int k=1; k<60; ++k) {
  real t=1*1.6pi*k/59;
  travel=travel--(1.5*cos(t),1.5*sin(t),0);
}
draw(surface(rim--cycle),gray(0.78)+opacity(0.38));
draw(rim--cycle,gray(0.35)+linewidth(0.7pt));
draw(travel,rgb(0.15,0.40,0.76)+linewidth(1.6pt),Arrow3);
draw(O--(0,0,1*1.9),rgb(0.79,0.17,0.14)+linewidth(1.6pt),Arrow3);
label("$\mathbf n=\mathbf k$",(0,0,1*1.9),2N);
label("counterclockwise",(0,-1.5,0),2S);

